def parse(path):
    records = []
    with open(path, encoding="utf-8") as handle:
        for raw in handle:
            line = raw.rstrip("\n")
            if not line.strip():
                continue
            # Skip continuation lines (lines starting with whitespace)
            if line.startswith("  "):
                continue
            match = LINE.match(line)
            if match:
                records.append({"ts": match["ts"], "level": match["level"], "service": match["service"], "msg": match["msg"]})
            # Traceback lines are not records and should be skipped
            elif line.startswith("Traceback"):
                continue
            else:
                records.append({"ts": None, "level": "UNKNOWN", "service": "", "msg": line})
    return records

